package com.bank.jvm;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Demonstrates Young Gen churn vs Old Gen long-lived residents.
public class GenerationDemo {
    private static final Logger log = Logger.getLogger(GenerationDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        GenReporter reporter = new GenReporter();

        // OLD GEN residents: a small cache of long-lived accounts.
        Map<String, Account> cache = new HashMap<>();
        cache.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        cache.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
        log.info(() -> "Long-lived cache populated with " + cache.size() + " accounts");
        reporter.report("Before churn");

        // YOUNG GEN churn: millions of short-lived transaction events, all die young.
        long totalTransfers = 0;
        for (int round = 0; round < 50; round++) {
            List<TransactionEvent> batch = new ArrayList<>();
            for (int i = 0; i < 50_000; i++) {
                batch.add(new TransactionEvent("txn-" + i, new BigDecimal("50000")));
            }
            totalTransfers += batch.size();
            // batch goes out of scope at end of iteration -> eligible for Minor GC
        }
        final long shown = totalTransfers;
        log.info(() -> "Processed " + shown + " short-lived transaction events");
        reporter.report("After churn (cache still alive)");
    }
}

