class GenReporter {
    private static final Logger log = Logger.getLogger(GenReporter.class.getName());

    void report(String label) {
        // Memory pools expose Young ("Eden"/"Survivor") and Old ("Old Gen"/"Tenured") usage.
        for (var pool : java.lang.management.ManagementFactory.getMemoryPoolMXBeans()) {
            String n = pool.getName();
            if (n.contains("Eden") || n.contains("Survivor") || n.contains("Old") || n.contains("Tenured")) {
                long used = pool.getUsage().getUsed() / (1024 * 1024);
                log.info(String.format("%s | %-28s used=%dMB", label, n, used));
            }
        }
        // GC counts: Minor (Young) vs Major (Old) collectors.
        for (var gc : java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            log.info(String.format("%s | GC %-22s count=%d time=%dms",
                    label, gc.getName(), gc.getCollectionCount(), gc.getCollectionTime()));
        }
    }
}
